function videoURL(value) {
    try {
        const u = new URL(value);
        if (!['https:', 'http:'].includes(u.protocol) || u.username || u.password) return '';
        const host = u.hostname.toLowerCase();
        let id = '';
        if (['youtube.com', 'www.youtube.com', 'm.youtube.com'].includes(host)) {
            id = u.pathname === '/watch' ? u.searchParams.get('v') : (/^\/(?:embed|shorts|live)\/([^/]+)\/?$/.exec(u.pathname) || [])[1];
        } else if (host === 'youtu.be') id = u.pathname.slice(1).replace(/\/$/, '');
        if (id && /^[\w-]{11}$/.test(id)) return 'https://www.youtube-nocookie.com/embed/' + id;
        if (['vimeo.com', 'www.vimeo.com', 'player.vimeo.com'].includes(host)) {
            const m = /^\/(?:video\/)?(\d+)(?:\/([a-zA-Z0-9]+))?\/?$/.exec(u.pathname);
            if (m) return 'https://player.vimeo.com/video/' + m[1] + (m[2] || u.searchParams.get('h') ? '?h=' + encodeURIComponent(m[2] || u.searchParams.get('h')) : '');
        }
    } catch (_) {}
    return '';
}
function render(d) {
    const el = id => document.getElementById(id);
    const text = (id, value) => { if (el(id)) el(id).textContent = value || 'Por definir'; };
    text('artista-nombre', d.nombre);
    text('artista-categoria', d.categoria);
    text('artista-descripcion-corta', d.descripcion);
    text('artista-ubicacion', d.ciudad);
    text('artista-especialidad', d.categoria);
    el('artista-ideal').previousElementSibling.textContent = 'Cobertura';
    text('artista-ideal', d.cobertura);
    text('artista-sobre-titulo', 'Sobre ' + d.nombre);
    text('artista-sobre-texto', d.descripcion);
    const portada = el('artista-portada');
    if (d.portada) { portada.src = d.portada; portada.alt = d.nombre; } else portada.remove();
    if (d.avatar) { const img = document.createElement('img'); img.src = d.avatar; img.alt = 'Foto de ' + d.nombre; img.style.cssText = 'width:88px;height:88px;border-radius:50%;object-fit:cover;margin-bottom:16px'; el('artista-nombre').before(img); }
    const galeria = el('artista-galeria'); galeria.replaceChildren();
    d.galeria.forEach(src => { const img = document.createElement('img'); img.src = src; img.alt = 'Galería de ' + d.nombre; galeria.append(img); });
    const video = document.querySelector('.perfil-video-placeholder'); video.replaceChildren();
    if (d.video) { const frame = document.createElement('iframe'); frame.src = d.video; frame.title = 'Video principal de ' + d.nombre; frame.allowFullscreen = true; frame.style.cssText = 'width:100%;aspect-ratio:16/9;border:0'; video.append(frame); }
    text('artista-repertorio-titulo', 'Géneros y estilos');
    const generos = el('artista-generos'); generos.replaceChildren();
    [...d.generos, ...d.subcategorias].forEach(value => { const span = document.createElement('span'); span.textContent = value.replaceAll('-', ' '); generos.append(span); });
    text('artista-repertorio-descripcion', d.decadas.length ? 'Décadas: ' + d.decadas.map(x => x === 'actual' ? 'Actual' : x).join(', ') : 'Consulta el repertorio disponible.');
    const shows = el('artista-shows'); shows.replaceChildren();
    const card = document.createElement('article'); card.className = 'show-card';
    ['h3', 'p', 'span'].forEach((tag,i) => { const child = document.createElement(tag); child.textContent = [d.servicio.nombre, d.servicio.incluye, d.servicio.duracion][i]; card.append(child); }); shows.append(card);
    document.querySelector('.perfil-operativo-grid').remove();
    const disponibilidad = document.querySelector('.perfil-disponibilidad p:not(.seccion-etiqueta)');
    disponibilidad.textContent = d.disponibilidad;
    document.querySelector('.perfil-similares').remove();
    // Las acciones de la maqueta no envían solicitudes ni cambian la navegación.
    document.querySelectorAll('a, button').forEach(a => { a.setAttribute('aria-disabled','true'); a.addEventListener('click', e => e.preventDefault()); });
    document.title = 'Vista previa — ' + d.nombre;
}
